import{_ as o,C as e,o as i,c as l,E as a,a2 as d}from"./chunks/framework.BOeh4kYD.js";const c="/joinwell52/assets/control-intent-20260917/retry-without-second-launch.figure.zh.svg",f=JSON.parse('{"title":"没收到回复，再点一次会启动两个 AI 吗？","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"没收到回复，再点一次会启动两个 AI 吗？","date":"2026-09-17","published_date":"2026-09-17","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"没收到回复，再点一次会启动两个 AI 吗？","summary":"请求可能已经成功，只是回复丢了。真实文件实验显示，安全重试有时返回原结果，有时必须承认不知道；这两种行为都在避免重复动作。","cover":"/assets/control-intent-20260917/retry-without-second-launch.cover-v1.png","language":"zh-CN","lifecycle":"Published","publication_authorized":true,"evidence_status":"固定源码有界实验；范围见正文","pageClass":"control-intent-article"},"headers":[],"relativePath":"zh/engineering/2026-09-17-retry-without-second-launch.md","filePath":"zh/engineering/2026-09-17-retry-without-second-launch.md","lastUpdated":1789614884000}'),s={name:"zh/engineering/2026-09-17-retry-without-second-launch.md"};function h(p,t,u,b,g,m){const r=e("ArticleCover"),n=e("ArticleTableScroll");return i(),l("div",null,[a(r,{image:"/assets/control-intent-20260917/retry-without-second-launch.cover-v1.png",kicker:"开源工程观察 · 实验研究",title:"没收到回复，再点一次会启动两个 AI 吗？",summary:"请求可能已经成功，只是回复丢了。真实文件实验显示，安全重试有时返回原结果，有时必须承认不知道；这两种行为都在避免重复动作。",version:"2026-09-17",languageHref:"/en/engineering/2026-09-17-retry-without-second-launch",languageLabel:"English"}),a(n,{language:"zh"}),t[0]||(t[0]=d('<h1 id="没收到回复-再点一次会启动两个-ai-吗" tabindex="-1">没收到回复，再点一次会启动两个 AI 吗？ <a class="header-anchor" href="#没收到回复-再点一次会启动两个-ai-吗" aria-label="Permalink to &quot;没收到回复，再点一次会启动两个 AI 吗？&quot;">​</a></h1><p>你在手机上按下“启动 AI 助手”，等了几秒，屏幕没有回应。</p><p>再按一次吗？如果第一次根本没送到，重试很合理。可如果电脑已经开始做事，只是回复丢了，第二次点击就可能又开出一份任务。</p><p>设想两个助手各自修改一套文件，你要分辨哪份该保留；重复工作还可能多占用资源。这些是重复启动的可能代价，不是本轮实验里已经发生的事故。它们让这个小小的点击值得认真对待：<strong>没收到回复，不能当作什么都没发生。</strong></p><h2 id="先查同一笔操作的记录" tabindex="-1">先查同一笔操作的记录 <a class="header-anchor" href="#先查同一笔操作的记录" aria-label="Permalink to &quot;先查同一笔操作的记录&quot;">​</a></h2><p>我们从 brennanb2025 提交的 <a href="https://github.com/stablyai/orca/pull/21106" target="_blank" rel="noreferrer">Orca #21106</a> 得到启发。Orca 让手机等远端设备与运行 AI 助手的电脑协作。这项修改给启动操作留下可保存到文件的记录，让重试能够找回已有结果。</p><p>我们关注它，是因为启动一个助手可能同时创建工作目录和会话。回答重复了，可以忽略一遍；工作启动了两份，后续影响却可能一直继续。</p><p>这里的办法是给每笔启动操作一个编号。第一次请求用它，重试仍用它，电脑便能先查原来的记录。这个编号在代码里叫“操作 ID”。检查时还要认清发起者和任务内容，避免有人拿旧编号去做一件新事情。</p><p>这项机制有一条关键分界：<strong>“我已接单”和“我已完成启动”，需要分别记录。</strong></p><h2 id="重试时-记录里留下了什么" tabindex="-1">重试时，记录里留下了什么？ <a class="header-anchor" href="#重试时-记录里留下了什么" aria-label="Permalink to &quot;重试时，记录里留下了什么？&quot;">​</a></h2><p>我们运行原项目中负责保存记录、判断是否允许启动的代码，用真实临时文件做实验。先写入一份合成的成功结果，丢弃第一次返回值，再发一次相同编号的启动请求。</p><p>这里的“成功结果”指启动这一步的结果，例如它返回了哪个工作目录；不表示助手已经完成后续任务。本轮没有启动真实助手。</p><table tabindex="0"><thead><tr><th>我们安排的情况</th><th>重试时观察到什么</th></tr></thead><tbody><tr><td>启动成功结果已经保存，但回复被丢弃</td><td>找回并返回同一份结果</td></tr><tr><td>只有“已接单”记录，没有最终结果</td><td>保留“未知”，拒绝再次放行</td></tr><tr><td>沿用同一编号，却改了任务内容</td><td>拒绝：这已经不是原来的请求</td></tr></tbody></table><p>第一行解释了记录的价值：回复可以丢，已经存好的结果还可以找回来。第三行说明编号不能随意套用。真正让人犹豫的，是第二行——既然已经接单，为什么不能继续？</p><p><img src="'+c+'" alt="同一个编号回来，先看记录是否完整"></p><p><em>图 1：来源：作者依据真实临时文件实验绘制。图中“完成”只指启动操作；成功结果是合成数据。</em></p><h2 id="接单以后-到底发生了什么" tabindex="-1">接单以后，到底发生了什么？ <a class="header-anchor" href="#接单以后-到底发生了什么" aria-label="Permalink to &quot;接单以后，到底发生了什么？&quot;">​</a></h2><p>假设电脑刚记下“我来执行”，便在保存最终结果之前失去联系。仅凭接单记录，至少有三种解释：尚未开始、已经做了一部分、已经完成启动但没来得及写回结果。</p><p>于是，“已接单”不能直接翻译成“还没做”，也不能翻译成“已成功”。再做一次可能制造重复；直接报成功，又可能让人等一项并不存在的工作。</p><p>受测代码保留了这种不确定性。它没有因为又收到同一个编号，就再发一张执行许可。我们还在同一进程内重新打开记录文件，已保存的成功结果仍能找回；不过，这不等于验证了断电或进程崩溃后的完整恢复。</p><p>截至本轮读取，这项修改已于 9 月 17 日 UTC 合入，但现有客户端尚未发送所需的外层操作编号。来源也明确把更广的恢复工作列在本次范围之外。因此，实验说明的是这层记录机制怎样处理重试，不能推成所有手机点击都已经受到保护。</p><h2 id="无法确认-之后-人还需要一个下一步" tabindex="-1">“无法确认”之后，人还需要一个下一步 <a class="header-anchor" href="#无法确认-之后-人还需要一个下一步" aria-label="Permalink to &quot;“无法确认”之后，人还需要一个下一步&quot;">​</a></h2><p>避免重复动作有价值，但使用者仍需要知道该等、该查，还是需要人工处理。</p><p>我们的实验把进一步的问题推向了“查证”：如果能查看原操作编号、仍在运行的任务，以及已经创建的资源，就有机会减少猜测。这些是后续设计与验证方向，本轮没有实现查询或接管流程。</p><p>使用者可以提供很具体的反馈：没有收到回复时，界面显示了什么，你随后做了什么，后来是否发现已有任务正在运行。这样的时间顺序，能帮助开发者分清“动作没发生”和“回复没回来”。</p><p><strong>当系统只能回答“暂时无法确认”时，它还应提供什么证据，才能让人放心决定下一步？</strong></p><details><summary>技术范围、固定版本与全部观察</summary><h3 id="保留的完整数值对照" tabindex="-1">保留的完整数值对照 <a class="header-anchor" href="#保留的完整数值对照" aria-label="Permalink to &quot;保留的完整数值对照&quot;">​</a></h3><p>“准入”指检查是否允许开始执行。下面八并发结果只在这一层观察；上层已有共享正在执行任务的处理，本轮未运行，因此七次拒绝不能外推成七次用户重试失败。</p><table tabindex="0"><thead><tr><th>安排的情况</th><th>原实现给出的结果</th></tr></thead><tbody><tr><td>成功结果已经保存，回复被丢弃</td><td>返回已保存的同一份结果</td></tr><tr><td>在同一进程重新打开记录存储，再重试</td><td>仍返回已保存的结果</td></tr><tr><td>同一操作 ID，换了任务内容</td><td>拒绝：内容冲突</td></tr><tr><td>同一配对设备，认证令牌轮换</td><td>仍识别为原操作并返回结果</td></tr><tr><td>只有“已接单”记录，没有最终结果</td><td>拒绝重做，保留“未知”</td></tr><tr><td>八个请求同时争取同一操作</td><td>一个获准执行，七个在准入层收到未知拒绝</td></tr></tbody></table><p>固定候选 <code>d60ff2db02bf2b6c6ac4fd39c179c9854409d2a4</code>；运行完整 durableAgentSessionRecordStore 和原始 admitAgentLaunchOperation、请求指纹与注册逻辑，使用真实临时文件和 proper-lockfile。11 条记录还覆盖不同配对设备隔离、已记录失败的重放、远端缺少配对身份、超过允许期限的新操作 ID。</p><p>不同发起设备可以拥有独立的同名操作；令牌轮换实验保持配对设备身份不变。八并发结果位于准入边界，上层 live join 未测。重新打开存储发生在同一进程。保存的成功结果是合成数据，没有实际创建工作目录、启动模型或调用移动端。</p><p><a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-17-control-intent" target="_blank" rel="noreferrer">结果与复跑脚本</a>。没有据此认定 CodeFlowMu 缺少幂等保护或存在重复启动缺陷。</p></details><p><a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">研究仓库</a></p>',28))])}const y=o(s,[["render",h]]);export{f as __pageData,y as default};
